"use client";

/*
 * EXIT Realty DKC logo, inlined as data URIs.
 *
 * Why inlined: the project's GitHub connection cannot transfer binary
 * files (its file API text-encodes uploads), so /public brand assets
 * cannot be pushed as real PNGs. The logo is small (~560px wide) and
 * inlining keeps it working everywhere with zero extra requests.
 * If binary uploads become available later, move these back to
 * /public/brand/ and switch to next/image.
 */

const GRADIENT =
  "data:image/png;base64," + '';

const WHITE =
  "data:image/png;base64," + '';

export function ExitLogo({
  variant = "gradient",
  className,
  alt = "EXIT Realty DKC",
}: {
  variant?: "gradient" | "white";
  className?: string;
  alt?: string;
}) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={variant === "white" ? WHITE : GRADIENT}
      alt={alt}
      className={className}
      draggable={false}
    />
  );
}
